Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fix bug introduced by 0099c46 that cause master to ignore
 incoming offer in trickle ice mode. In viewer sample, generate random client
 id each time

Here is the root cause:
The bug was caused by the master ignoring incoming offers in trickle ICE mode due to the logic that did not properly handle the state of offer processing. Specifically, the previous implementation did not track whether an offer had already been received for a given client ID, leading to potential overwriting or ignoring of valid offers. The introduction of the `sdpOfferAnswerExchanged` variable allows for proper tracking of this state, ensuring that duplicate offers from the same client ID are ignored.

Here is the patch:

 STATUS masterMessageReceived(UINT64 customData, PReceivedSignalingMessage pReceivedSignalingMessage)
 {
     STATUS retStatus = STATUS_SUCCESS;
     PSampleConfiguration pSampleConfiguration = (PSampleConfiguration) customData;
     PSampleStreamingSession pSampleStreamingSession = NULL;
     UINT32 i;
-    BOOL locked = FALSE, sessionExisted = FALSE;
+    BOOL locked = FALSE;
+    ATOMIC_BOOL expected = FALSE;

     CHK(pSampleConfiguration != NULL, STATUS_NULL_ARG);

     MUTEX_LOCK(pSampleConfiguration->sampleConfigurationObjLock);
     locked = TRUE;
-
     // ice candidate message and offer message can come at any order. Therefore, if we see a new peerId, then create
     // a new SampleStreamingSession, which in turn creates a new peerConnection
     for (i = 0; i < pSampleConfiguration->streamingSessionCount && pSampleStreamingSession == NULL; ++i) {
         if (0 == STRCMP(pReceivedSignalingMessage->signalingMessage.peerClientId, pSampleConfiguration->sampleStreamingSessionList[i]->peerId)) {
             pSampleStreamingSession = pSampleConfiguration->sampleStreamingSessionList[i];
-            sessionExisted = TRUE;
         }
     }

     if (pSampleStreamingSession == NULL) {
         CHK_WARN(pSampleConfiguration->streamingSessionCount < ARRAY_SIZE(pSampleConfiguration->sampleStreamingSessionList),
                  retStatus, "Dropping signalling message from peer %s since maximum simultaneous streaming session of %u is reached",
                  pReceivedSignalingMessage->signalingMessage.peerClientId, ARRAY_SIZE(pSampleConfiguration->sampleStreamingSessionList));

         DLOGD("Creating new streaming session for peer %s", pReceivedSignalingMessage->signalingMessage.peerClientId);
         CHK_STATUS(createSampleStreamingSession(pSampleConfiguration,
                                                        pReceivedSignalingMessage->signalingMessage.peerClientId,
                                                        TRUE,
                                                        &pSampleStreamingSession));
         pSampleConfiguration->sampleStreamingSessionList[pSampleConfiguration->streamingSessionCount++] = pSampleStreamingSession;
     }

     MUTEX_UNLOCK(pSampleConfiguration->sampleConfigurationObjLock);
     locked = FALSE;

     switch (pReceivedSignalingMessage->signalingMessage.messageType) {
         case SIGNALING_MESSAGE_TYPE_OFFER:
-            if (!sessionExisted) {
+            if (ATOMIC_COMPARE_EXCHANGE_BOOL(&pSampleStreamingSession->sdpOfferAnswerExchanged, &expected, TRUE)) {
                 CHK_STATUS(handleOffer(pSampleConfiguration,
                                        pSampleStreamingSession,
                                        &pReceivedSignalingMessage->signalingMessage));
             } else {
-                DLOGD("session still active, ignore new offer that has the same client id");
+                DLOGD("Offer already received, ignore new offer from client id %s",
+                      pReceivedSignalingMessage->signalingMessage.peerClientId);
             }
             break;
         case SIGNALING_MESSAGE_TYPE_ICE_CANDIDATE:
             CHK_STATUS(handleRemoteCandidate(pSampleStreamingSession, &pReceivedSignalingMessage->signalingMessage));
             break;
         case SIGNALING_MESSAGE_TYPE_ANSWER:
             DLOGE("Unexpected message SIGNALING_MESSAGE_TYPE_ANSWER \n");
             break;
         default:
             DLOGW("Unknown message type %u", pReceivedSignalingMessage->signalingMessage.messageType);
     }

 CleanUp:

     if (locked) {
         MUTEX_UNLOCK(pSampleConfiguration->sampleConfigurationObjLock);
     }

     // Return success to continue
     return retStatus;
 }



